void Solver::bump_var(int var, double coeff) {
    const double THRESH = 1e100;
    const double SCALE  = 1e-100;

    // If the global increment is too large, down‑scale all activities once.
    if (var_inc > THRESH) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Increase activity of the given variable.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Clamp the variable's activity to avoid immediate overflow.
    if (activity[var] > THRESH) activity[var] = THRESH;

    // Keep the VSIDS heap up‑to‑date.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
